/* 5. OFFLINE APP SHELL — generated by tools/update-cache.mjs.
   Publish the entire package together. Updates wait for a student to reload.
   Catalogue data is saved separately in IndexedDB; POSTs and remote files are never cached here. */
'use strict';
const CACHE_PREFIX = 'imsc-library-shell-';
const CACHE_NAME = '__CACHE_ID__';
const PRECACHE_PATHS = __PRECACHE_PATHS__;
const BASE = self.registration.scope;
const absolute = path => new URL(path, BASE).href;
const INDEX_URL = absolute('./index.html');
const OFFLINE_URL = absolute('./offline.html');
const SHELL_URLS = new Set(PRECACHE_PATHS.map(absolute));

self.addEventListener('install', event => {
  event.waitUntil((async () => {
    const cache = await caches.open(CACHE_NAME);
    // addAll fails installation if even one required local asset is unavailable.
    await cache.addAll(PRECACHE_PATHS.map(path => new Request(absolute(path), { cache: 'reload' })));
    // No skipWaiting here: an existing active release remains intact.
  })());
});

self.addEventListener('message', event => {
  if (event.data && event.data.type === 'SKIP_WAITING') event.waitUntil(self.skipWaiting());
});

self.addEventListener('activate', event => {
  event.waitUntil((async () => {
    const names = await caches.keys();
    await Promise.all(names.filter(name => name.startsWith(CACHE_PREFIX) && name !== CACHE_NAME).map(name => caches.delete(name)));
    await self.clients.claim();
  })());
});

async function shellResponse(request, key, fallback) {
  const cache = await caches.open(CACHE_NAME);
  const saved = await cache.match(key);
  if (saved) return saved;
  try {
    const response = await fetch(request);
    if (response.ok) return response;
    if (!fallback) return response;
  } catch (_) { /* Use a self-contained fallback when the shell is unavailable. */ }
  if (fallback) {
    const offline = await cache.match(OFFLINE_URL);
    if (offline) return offline;
    return new Response('<!doctype html><title>Offline</title><h1>You are offline</h1><p>Reconnect and reopen the library.</p>', {
      status: 503, headers: { 'Content-Type': 'text/html; charset=utf-8' }
    });
  }
  return Response.error();
}

self.addEventListener('fetch', event => {
  const request = event.request;
  if (request.method !== 'GET') return;
  const url = new URL(request.url);
  const scope = new URL(BASE);
  if (url.origin !== scope.origin) return;
  // Only the library page is a navigation fallback. A document URL is never replaced by HTML.
  if (request.mode === 'navigate' && (url.pathname === scope.pathname || url.pathname === new URL(INDEX_URL).pathname)) {
    event.respondWith(shellResponse(request, INDEX_URL, true));
    return;
  }
  if (SHELL_URLS.has(url.href)) event.respondWith(shellResponse(request, url.href, false));
});
